#!/bin/bash

cd "${GITHUB_WORKSPACE}"

OPTION_LIST=(
    "-DWINDOWS_RUB_INCLUDE:PATH=${DEPENDS_BUILD_PREFIX}/${WINDOWSRUB_NAME}/include"
    "-DCXXOPTS_ROOT:PATH=${DEPENDS_BUILD_PREFIX}/${CXXOPTS_NAME}"
    "-DFFMPEG_ROOT:PATH=${DEPENDS_BUILD_PREFIX}/${FFMPEG_NAME}/${DEPENDS_BUILD_LOCAL}"
)
echo "${OPTION_LIST[@]}"

cmake -B "${BUILD_PATH}" \
"${OPTION_LIST[@]}" \
&& \
cmake --build "${BUILD_PATH}" --config Release